// Package icons holds the one Lucide icon that examples/pricing uses, as a
// tela.Icon variable generated by `tela icons gen` from the SVG file in this
// directory. It is a subset of the separate module
// github.com/kuronosu/tela/icons/lucide (the core module cannot import it),
// with the drawing of lucide-static 1.61.0 and Lucide's license file
// (LICENSE).
//
// To change the set, add or remove SVG files here and run
//
//	go generate ./examples/pricing/icons
//
//go:generate go run github.com/kuronosu/tela/cmd/tela icons gen -pkg icons -o . -source "Lucide 1.61.0 (lucide-static, https://lucide.dev)" -license ISC -license-file LICENSE .
package icons
